import{_ as a,C as i,o as s,c as r,j as t,a as n,E as l,a2 as u}from"./chunks/framework.BxGh02fV.js";const v=JSON.parse('{"title":"Git","description":"","frontmatter":{"title":"Git"},"headers":[],"relativePath":"guide/git.md","filePath":"guide/git.md"}'),c={name:"guide/git.md"};function m(d,e,h,p,f,g){const o=i("Capture");return s(),r("div",null,[e[0]||(e[0]=t("h1",{id:"git",tabindex:"-1"},[n("Git "),t("a",{class:"header-anchor",href:"#git","aria-label":'Permalink to "Git"'},"​")],-1)),e[1]||(e[1]=t("p",null,"Cet écran montre l'état git local du workspace et permet de committer les métadonnées d'Effortless sans quitter l'application. Vous y venez pour voir ce qui a changé, ou pour enregistrer l'état du suivi dans l'historique.",-1)),l(o,{name:"git",alt:"L'écran Git : branche, liste des fichiers modifiés"}),e[2]||(e[2]=u('<h2 id="ce-que-vous-voyez" tabindex="-1">Ce que vous voyez <a class="header-anchor" href="#ce-que-vous-voyez" aria-label="Permalink to &quot;Ce que vous voyez&quot;">​</a></h2><p>Sous le titre <strong>Git (local)</strong>, trois cartes se suivent de haut en bas. La capture n&#39;en montre que le début ; faites défiler l&#39;écran pour voir la suite.</p><ol><li><strong>Branche</strong> et <strong>Fichiers modifiés</strong> : la branche courante, puis la liste des fichiers modifiés. Si l&#39;arbre est propre, l&#39;écran affiche « Répertoire de travail propre. » Si le dossier n&#39;est pas un dépôt, il affiche « Ce répertoire n&#39;est pas un dépôt git. »</li><li><strong>Auto-commit des métadonnées</strong>, <strong>Message de commit</strong> et le bouton <strong>Committer les métadonnées</strong>.</li><li><strong>Derniers commits</strong> : un tableau (<strong>Hash</strong>, <strong>Sujet</strong>, <strong>Date</strong>) des dix derniers commits, et un bouton <strong>Rafraîchir</strong>.</li></ol><h2 id="ce-que-vous-pouvez-faire" tabindex="-1">Ce que vous pouvez faire <a class="header-anchor" href="#ce-que-vous-pouvez-faire" aria-label="Permalink to &quot;Ce que vous pouvez faire&quot;">​</a></h2><h3 id="activer-l-auto-commit" tabindex="-1">Activer l&#39;auto-commit <a class="header-anchor" href="#activer-l-auto-commit" aria-label="Permalink to &quot;Activer l&#39;auto-commit&quot;">​</a></h3><p>Cochez <strong>Auto-commit des métadonnées</strong>. Effortless committe alors automatiquement <code>.effortless</code> et <code>blueprints</code> après chaque action faite dans l&#39;application (ADR, BQO, tâche, phase). Il ne committe jamais de code. Chaque auto-commit s&#39;annonce par une notification (« Auto-commit … » suivi du hash), ou dit pourquoi il a été ignoré.</p><p>La case n&#39;est pas mémorisée : elle repart décochée quand vous revenez au sélecteur ou aux préférences, et à chaque lancement.</p><h3 id="committer-les-metadonnees-a-la-main" tabindex="-1">Committer les métadonnées à la main <a class="header-anchor" href="#committer-les-metadonnees-a-la-main" aria-label="Permalink to &quot;Committer les métadonnées à la main&quot;">​</a></h3><ol><li>Saisissez un <strong>Message de commit</strong>. S&#39;il reste vide, Effortless utilise <code>chore(effortless): mise à jour des métadonnées</code>.</li><li>Cliquez sur <strong>Committer les métadonnées</strong>.</li></ol><p>L&#39;écran affiche « Commit créé : » suivi du hash. Le bouton est désactivé si le dossier n&#39;est pas un dépôt git.</p><h3 id="relire-l-historique" tabindex="-1">Relire l&#39;historique <a class="header-anchor" href="#relire-l-historique" aria-label="Permalink to &quot;Relire l&#39;historique&quot;">​</a></h3><p>Cliquez sur <strong>Rafraîchir</strong> pour relire l&#39;état et la liste des commits.</p><h2 id="conseils" tabindex="-1">Conseils <a class="header-anchor" href="#conseils" aria-label="Permalink to &quot;Conseils&quot;">​</a></h2><ul><li>Ce bouton ne committe que les métadonnées. Vos fichiers de code restent à committer vous-même ; le hook de l&#39;écran <a href="/Effortless/guide/drift.html">Dérive</a> vérifiera alors qu&#39;une tâche est en cours.</li><li>Une branche affichée « (aucune) » signifie que le dépôt n&#39;a pas encore de commit ou n&#39;est pas rattaché à une branche. Sans aucun commit, le tableau affiche « Aucun commit dans l&#39;historique. »</li></ul>',14))])}const b=a(c,[["render",m]]);export{v as __pageData,b as default};
